"""Diagnostic: walk the RData tree of repo/data/intCars.rda and dump structure."""
import sys, json
import numpy as np
import rdata
from rdata.parser import RObjectType

path = sys.argv[1] if len(sys.argv) > 1 else 'repo/data/intCars.rda'
parsed = rdata.parser.parse_file(path)


def attrs(node):
    a = getattr(node, 'attributes', None)
    out = {}
    if a is None:
        return out
    # attributes is a LIST of tag->value pairs
    try:
        cur = a
        while cur is not None and getattr(cur, 'tag', None) is not None:
            tag = cur.tag.value.value.decode()
            val = cur.value
            out[tag] = summarize(val, depth=0)
            cur = cur.attributes if getattr(cur, 'tag', None) is not None else None
    except Exception as e:
        out['<error>'] = str(e)
    return out


def summarize(node, depth=0):
    if node is None:
        return None
    t = node.value_type if hasattr(node, 'value_type') else None
    name = str(getattr(node, 'value_type', ''))
    return {'type': name, 'depth': depth}


def walk(node, depth=0, maxdepth=40):
    lines = []
    prefix = '  ' * depth
    vt = str(getattr(node, 'value_type', '?'))
    if vt.endswith('NIL') or node is None:
        return [f"{prefix}NIL"]
    if depth > maxdepth:
        return [f"{prefix}...maxdepth"]
    val = getattr(node, 'value', None)
    a = attrs(node)
    astr = ''
    if a:
        astr = ' attrs=' + json.dumps({k: (v if not isinstance(v, dict) else v.get('type')) for k, v in a.items()}, default=str)
    if vt in ('REAL', 'INT', 'LGL', 'STR', 'RAW'):
        if isinstance(val, (list, tuple)):
            shown = list(val[:6])
            lines.append(f"{prefix}{vt} n={len(val)} head={shown}{astr}")
        else:
            lines.append(f"{prefix}{vt} {val!r}{astr}")
    elif vt in ('VEC', 'LIST'):
        lines.append(f"{prefix}{vt}{astr}")
        # LIST: tag + value + attributes chain ; VEC: iterable of items
        if hasattr(val, 'value_type') and 'LIST' in vt:
            cur = node
            while cur is not None:
                tag = cur.tag
                tagname = tag.value.value.decode() if (tag is not None and getattr(tag, 'value', None) is not None) else '?'
                lines.append(f"{prefix}  [{tagname}]")
                lines.extend(walk(cur.value, depth + 2, maxdepth))
                nxt = getattr(cur, 'attributes', None)
                if nxt is None or getattr(nxt, 'value_type', '').endswith('NIL'):
                    break
                cur = nxt
        else:
            if isinstance(val, (list, tuple)):
                for i, item in enumerate(val):
                    lines.append(f"{prefix}  item{i}")
                    lines.extend(walk(item, depth + 2, maxdepth))
            else:
                lines.extend(walk(val, depth + 1, maxdepth))
    else:
        lines.append(f"{prefix}{vt}{astr}")
        if isinstance(val, (list, tuple)):
            for i, item in enumerate(val):
                lines.append(f"{prefix}  sub{i}")
                lines.extend(walk(item, depth + 1, maxdepth))
        elif hasattr(val, 'value_type'):
            lines.extend(walk(val, depth + 1, maxdepth))
        tg = getattr(node, 'tag', None)
        if tg is not None and hasattr(tg, 'value_type'):
            lines.append(f"{prefix}  tag:")
            lines.extend(walk(tg, depth + 2, maxdepth))
    return lines


out = walk(parsed.object if hasattr(parsed, 'object') else parsed, 0)
text = "\n".join(out)
with open('results/rda_structure.txt', 'w', encoding='utf-8') as fh:
    fh.write(text)
print(text[:6000])

