"""Diagnostic: convert intCars.rda tree to nested python and dump structure."""
import sys, json
import numpy as np
import rdata
from rdata.parser import RObjectType


def attr_map(node):
    """Attributes are stored as a pairlist chain of LIST nodes."""
    out = {}
    cur = node
    while cur is not None and cur.info.type in (RObjectType.LIST, RObjectType.ATTRLIST):
        tag = cur.tag
        name = tag.value.value.decode() if isinstance(tag.value, dict) or tag.value is not None else None
        try:
            name = tag.value.value.decode()
        except Exception:
            name = str(tag.value)
        out[name] = cur.value
        cur = cur.attributes
    return out


def to_py(node, depth=0):
    if node is None:
        return None
    t = node.info.type
    if t in (RObjectType.NIL, RObjectType.NILVALUE):
        return None
    if t == RObjectType.REF:
        return to_py(node.referenced_object, depth)
    if t == RObjectType.SYM:
        return {'__sym__': node.value.value.decode() if node.value is not None else None}
    if t == RObjectType.CHAR:
        return node.value.decode('utf-8', 'replace') if isinstance(node.value, (bytes, bytearray)) else node.value
    if t in (RObjectType.REAL, RObjectType.INT, RObjectType.LGL, RObjectType.STR, RObjectType.RAW, RObjectType.CPLX):
        vals = node.value
        if isinstance(vals, np.ndarray):
            vals = vals.tolist()
        a = attr_map(node.attributes) if node.attributes else {}
        if 'dim' in a:
            dim = [int(x) for x in to_py(a['dim'], depth + 1)]
            arr = np.array(vals, dtype=float if t == RObjectType.REAL else object)
            arr = arr.reshape(dim, order='F')
            return arr
        if t == RObjectType.INT and 'levels' in a:
            lv = to_py(a['levels'], depth + 1)
            return [None if v is None or v == -2147483648 else lv[int(v) - 1] for v in vals]
        return vals
    if t == RObjectType.VEC:
        vals = node.value
        items = [to_py(v, depth + 1) for v in vals]
        a = attr_map(node.attributes) if node.attributes else {}
        if 'names' in a:
            names = to_py(a['names'], depth + 1)
            return dict(zip(names, items))
        if 'dim' in a:
            return items
        return items
    if t in (RObjectType.LIST, RObjectType.ATTRLIST):
        d = {}
        cur = node
        while cur is not None and cur.info.type in (RObjectType.LIST, RObjectType.ATTRLIST):
            tag = cur.tag
            try:
                name = tag.value.value.decode()
            except Exception:
                name = f'__anon{len(d)}'
            d[name] = to_py(cur.value, depth + 1)
            cur = cur.attributes
        return d
    if t == RObjectType.S4:
        # S4: value is list of slot values; class name in attributes$class
        a = attr_map(node.attributes) if node.attributes else {}
        cls = to_py(a.get('class'), depth + 1)
        vals = node.value
        if isinstance(vals, RObject):
            vals = [vals]
        slots = [to_py(v, depth + 1) for v in vals]
        return {'__S4__': cls, '__slots__': slots, '__attrs__': {k: None for k in a}}
    return {'__unhandled__': str(t)}


