  //   Returns:
  //   

  if (x.is_empty()) {
    return 0.0;
  }
  arma::uvec idx = arma::find_finite(x); //indices of finite elements 
  double m0,s0,mu;
  if(!std::isfinite(initLoc)) { 
    m0 = arma::median(x.elem(idx));
  } else {
    m0 = initLoc;
  }
  if(!std::isfinite(initScale)) { 
    s0 =  1.482602218505602 * arma::median(arma::abs(x.elem(idx) - m0));
  } else {
    s0 = initScale;
  }
  if(s0 > precScale) {
