YJ <- function(y, lambda, chg = NULL, stdToo = TRUE) {

  # The Yeo-Johnson transformation.

  #

indlow  <- which(y < 0)

indhigh <- which(y >= 0)

if (lambda != 0) {

  y[indhigh] = ((1 + y[indhigh])^(lambda) - 1) / lambda

} else { 

  y[indhigh] = log(1 + y[indhigh])

}

if (lambda != 2) {

  y[indlow] = -((1 - y[indlow])^(2 - lambda) - 1) / (2 - lambda)

