  if (length(y) > 1) {

    locScale <- estLocScale(matrix(y, ncol = 1), 

                            type = "hubhub")

    zt <- (y - locScale$loc) / locScale$scale

  } else {

    zt <- y

  }

  } else {

    zt <- NULL

  }

  return(list(yt = y, zt = zt))

}





